class Solution {
public:
    int maxKilledEnemies(vector<vector<char>>& grid) {
        if (grid.empty() || grid[0].empty()) return 0;
        int m = grid.size(), n = grid[0].size();
        int maxEnemies = 0;
        int rowHits = 0;
        vector<int> colHits(n, 0);
        for (int r = 0; r < m; ++r) {
            for (int c = 0; c < n; ++c) {
                if (c == 0 || grid[r][c - 1] == 'W') {
                    rowHits = 0;
                    for (int k = c; k < n && grid[r][k] != 'W'; ++k) {
                        if (grid[r][k] == 'E') rowHits++;
                    }
                }
                if (r == 0 || grid[r - 1][c] == 'W') {
                    colHits[c] = 0;
                    for (int k = r; k < m && grid[k][c] != 'W'; ++k) {
                        if (grid[k][c] == 'E') colHits[c]++;
                    }
                }
                if (grid[r][c] == '0') {
                    maxEnemies = max(maxEnemies, rowHits + colHits[c]);
                }
            }
        }
        return maxEnemies;
    }
};

class Solution {
    public int maxKilledEnemies(char[][] grid) {
        if (grid == null || grid.length == 0 || grid[0].length == 0) return 0;
        int m = grid.length, n = grid[0].length;
        int maxEnemies = 0;
        int rowHits = 0;
        int[] colHits = new int[n];
        for (int r = 0; r < m; r++) {
            for (int c = 0; c < n; c++) {
                if (c == 0 || grid[r][c - 1] == 'W') {
                    rowHits = 0;
                    for (int k = c; k < n && grid[r][k] != 'W'; k++) {
                        if (grid[r][k] == 'E') rowHits++;
                    }
                }
                if (r == 0 || grid[r - 1][c] == 'W') {
                    colHits[c] = 0;
                    for (int k = r; k < m && grid[k][c] != 'W'; k++) {
                        if (grid[k][c] == 'E') colHits[c]++;
                    }
                }
                if (grid[r][c] == '0') {
                    maxEnemies = Math.max(maxEnemies, rowHits + colHits[c]);
                }
            }
        }
        return maxEnemies;
    }
}

