var maxKilledEnemies = function(grid) {
    if (!grid || grid.length === 0 || grid[0].length === 0) return 0;
    const m = grid.length, n = grid[0].length;
    let maxEnemies = 0;
    let rowHits = 0;
    const colHits = new Array(n).fill(0);
    for (let r = 0; r < m; r++) {
        for (let c = 0; c < n; c++) {
            if (c === 0 || grid[r][c - 1] === 'W') {
                rowHits = 0;
                for (let k = c; k < n && grid[r][k] !== 'W'; k++) {
                    if (grid[r][k] === 'E') rowHits++;
                }
            }
            if (r === 0 || grid[r - 1][c] === 'W') {
                colHits[c] = 0;
                for (let k = r; k < m && grid[k][c] !== 'W'; k++) {
                    if (grid[k][c] === 'E') colHits[c]++;
                }
            }
            if (grid[r][c] === '0') {
                maxEnemies = Math.max(maxEnemies, rowHits + colHits[c]);
            }
        }
    }
    return maxEnemies;
};
